FREE_FEATURES = "Ad visible in all lists and searches\nUp to 12 pictures\nGreen Free frame\nRenew for free when less than 7 days are left"
BRONZE_FEATURES = "Everything in Free\nBronze frame and ribbon\nShown above Free ads"


def four_plans(apps, schema_editor):
    """Basic → Bronze (paid), Platinum → Diamond, and a new Free plan (0 kr). Unpaid ads become Free."""
    Ad, Plan, Product, Order, Offer = (apps.get_model("core", m) for m in ("Ad", "Plan", "Product", "Order", "Offer"))
    for model in (Order, Offer):
        model.objects.filter(tier="basic").update(tier="bronze")
        model.objects.filter(tier="platinum").update(tier="diamond")
    # Ads never had a paid Basic tier (Basic only extended the run time), so Basic ads are Free.
    Ad.objects.filter(tier="basic").update(tier="free", tier_until=None)
    Ad.objects.filter(tier="platinum").update(tier="diamond")

    renames = {"basic": ("bronze", "Bronze", "Shown above Free ads, with a bronze frame.", BRONZE_FEATURES, 1),
               "platinum": ("diamond", "Diamond", "Maximum visibility: top of every list and the front-page slider.", None, 3)}
    for old, (new, name, desc, features, order) in renames.items():
        plan = Plan.objects.filter(tier=old).first()
        if plan:
            plan.tier, plan.name, plan.description, plan.sort_order = new, name, desc, order
            if features:
                plan.features = features
            plan.features = plan.features.replace("Platinum", "Diamond").replace("Basic", "Bronze")
            plan.save()
        for p in Product.objects.filter(tier=old, kind="plan"):
            p.tier = new
            p.code = p.code.replace(old, new, 1)
            p.name = p.name.replace(old.title(), name)
            p.save()
    gold = Plan.objects.filter(tier="gold").first()
    if gold:
        gold.sort_order = 2
        gold.features = gold.features.replace("Everything in Basic", "Everything in Bronze").replace(
            "Shown above Basic ads", "Shown above Bronze and Free ads").replace("Featured badge", "ribbon")
        gold.save()
    free, _ = Plan.objects.get_or_create(tier="free", defaults={
        "name": "Free", "description": "Get your ad online for free.", "features": FREE_FEATURES, "sort_order": 0})
    for days, label in ((7, "1 week"), (30, "1 month")):
        Product.objects.update_or_create(code=f"free-{days}d", defaults={
            "kind": "plan", "plan": free, "name": f"Free – {label}", "tier": "free", "days": days, "price": 0,
            "currency": "DKK", "is_active": True, "sort_order": 0})


